select 'table' as kind,n.nspname as schema_name,c.relname as name,c.relrowsecurity as rls,c.relacl::text as acl from pg_class c join pg_namespace n on n.oid=c.relnamespace where n.nspname in ('public','private','storage') and (c.relname ~* '(jra.*(snapshot|audit|rank|worker)|html|archive|buckets)') and c.relkind in ('r','p','v','m') union all select 'function',n.nspname,p.proname,p.prosecdef,p.proacl::text from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname in ('public','private') and p.proname ~* '(jra.*(html|archive|snapshot)|read.*body)' order by kind,schema_name,name limit 100;
